event.script:
if(!controlScript.dateFormatChange(this))
{	
	form1.MainPage.subfrmMain.txtLC.rawValue = this.rawValue;
	form1.MainPage.subfrmMain.btnLC.execEvent("click");
}		


if (this.rawValue == null)
		controlScript.currentDate( this );

