function currentDate(field)
{
	var now = new Date();
	var date = now.getDate();
	var month = now.getMonth();
	var year = now.getFullYear();

	month=month+1;

	year=year.toString();

	if (date<10)
	{
   	  date=date.toString();
 	  date=0+date;
	}
	else
	   	date=date.toString();

	if (month<10)
	{
   		month=month.toString();
   		month=0+month;
	}
	else
   		month=month.toString();  

	var aa=new Date(year,month,date);

	if (field == null)
		return year+"-"+month+"-"+date;
	else
		field.rawValue =year+"-"+month+"-"+date;
}


