function trim(stringToTrim){
	if(stringToTrim != null)
		stringToTrim  = stringToTrim.toString();
	if(stringToTrim == null || stringToTrim.length == 0)
		return null;
	else
		return ltrim(rtrim(stringToTrim));
}

