	if(strThirdAdd == "")
		strThirdAdd = null;		 

	var temp2 = '';
	var barcodeString2 = '';

	var barcodeString2 = '2'+'|';																									//2_01

	temp2 = form1.DBRP.subfrmAPF.subfrm3PartyBeneficiary.txtName.rawValue;															//2_02
