	barcodeString2 = barcodeString2 + (temp2 == null? '':temp2) + '|'; 

	//xfa.host.messageBox(barcodeString2 );
 	form1.DBRP.subfrmAPFFoot.subfrmBarcodeRecord.txtBarcode2.rawValue = barcodeString2; 
}

